import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import net.farmingtales.ftboss.boss.ai.NativeManorDamageBridgeInstaller;
public final class TeaOriginalCastActualLoadedAuditV1 {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static ClassNode read(byte[] bytes){ClassNode node=new ClassNode();new ClassReader(bytes).accept(node,ClassReader.SKIP_FRAMES);return node;}
    private static Map<String,String> graphs(ClassNode node){Map<String,String> values=new TreeMap<>();for(MethodNode method:node.methods)values.put(method.name+method.desc,NativeManorDamageBridgeInstaller.graph(method));return values;}
    private static ClassNode copy(ClassNode node){ClassNode result=new ClassNode();node.accept(result);return result;}
    public static void main(String[] args)throws Exception{
        Path directory=Path.of(args[0]);List<String> names=List.of("entity/TeaTreeBossEntity","client/model/SayaPlayerModel","integ/spells/BossSpellCombat","saya/SayaCastData","saya/SayaCastMotion","saya/SayaCastSync","saya/SayaCastLifecycle","saya/SayaCastCancellation","client/saya/SayaCastingPose","client/saya/SayaCastingPose$Memory");Map<String,ClassNode> expected=new HashMap<>(),actual=new HashMap<>();
        try(ZipFile jar=new ZipFile(args[1])){for(String suffix:names){String name="net/farmingtales/ftboss/"+suffix;byte[] payload=jar.getInputStream(jar.getEntry(name+".class")).readAllBytes(),defined=Files.readAllBytes(directory.resolve(name.replace('/','_')+".class"));require(Arrays.equals(payload,defined),"Actual loaded class equals frozen candidate "+suffix);ClassNode before=read(payload),current=read(defined);require(graphs(before).equals(graphs(current)),"Actual complete method graphs equal candidate "+suffix);expected.put(suffix,before);actual.put(suffix,current);}}
        ClassNode combat=actual.get("integ/spells/BossSpellCombat");long accelerated=combat.methods.stream().flatMap(method->Arrays.stream(method.instructions.toArray())).filter(instruction->instruction instanceof MethodInsnNode call&&call.name.equals("acceleratedTicks")).count(),parallel=combat.methods.stream().flatMap(method->Arrays.stream(method.instructions.toArray())).filter(instruction->instruction instanceof MethodInsnNode call&&call.name.equals("parallelSpells")).count();require(accelerated==3&&parallel==0,"Actual global class preserves original three accelerations and no parallel call");
        ClassNode cancellation=actual.get("saya/SayaCastCancellation");require(cancellation.methods.stream().filter(method->method.name.equals("tick")).allMatch(method->method.desc.equals("(Lnet/neoforged/neoforge/event/tick/EntityTickEvent$Pre;)V")),"Actual LOWEST cancellation attached to same public Pre tick boundary as original scheduler");boolean gameBus=false,lowest=false;for(AnnotationNode annotation:cancellation.visibleAnnotations)if(annotation.desc.equals("Lnet/neoforged/fml/common/EventBusSubscriber;"))for(int index=0;index<annotation.values.size();index+=2)if(annotation.values.get(index).equals("bus"))gameBus=((String[])annotation.values.get(index+1))[1].equals("GAME");for(MethodNode method:cancellation.methods)if(method.name.equals("tick")&&method.visibleAnnotations!=null)for(AnnotationNode annotation:method.visibleAnnotations)if(annotation.desc.equals("Lnet/neoforged/bus/api/SubscribeEvent;"))for(int index=0;index<annotation.values.size();index+=2)if(annotation.values.get(index).equals("priority"))lowest=((String[])annotation.values.get(index+1))[1].equals("LOWEST");require(gameBus&&lowest,"Actual original cancellation uses GAME bus and LOWEST priority");
        int negatives=0;for(String suffix:List.of("entity/TeaTreeBossEntity","client/model/SayaPlayerModel","integ/spells/BossSpellCombat","saya/SayaCastData")){ClassNode damaged=copy(actual.get(suffix));boolean changed=false;for(MethodNode method:damaged.methods){for(AbstractInsnNode instruction:method.instructions){if(suffix.equals("entity/TeaTreeBossEntity")&&method.name.equals("startSignatureCast")&&instruction instanceof MethodInsnNode call&&call.name.equals("duration")){call.name="wrongDuration";changed=true;break;}if(suffix.equals("client/model/SayaPlayerModel")&&instruction instanceof MethodInsnNode call&&call.owner.endsWith("/SayaCastingPose")){call.name="wrongPose";changed=true;break;}if(suffix.equals("integ/spells/BossSpellCombat")&&instruction instanceof LdcInsnNode constant&&Long.valueOf(60).equals(constant.cst)){constant.cst=61L;changed=true;break;}if(suffix.equals("saya/SayaCastData")&&instruction instanceof LdcInsnNode constant&&constant.cst instanceof Double number){constant.cst=number+0.125D;changed=true;break;}}if(changed)break;}require(changed&&!graphs(expected.get(suffix)).equals(graphs(damaged)),"Negative changed actual original graph rejected "+suffix);negatives++;}
        System.out.println("{\"checks\":"+checks+",\"actualClassCount\":"+names.size()+",\"negativeControls\":"+negatives+",\"allActualGraphsExactlyCandidate\":true,\"threeOriginalAcceleratedCallsites\":true,\"originalSingleSpellOnly\":true,\"actualCancellationGameLowest\":true,\"modelOrAnimationValuesExported\":false}");
    }
}
